324	import { useEffect, useReducer, useState } from "react";
325	import { readResponse, type ChatAnswer } from "./use-chat-request";
326	import { VoiceCallController, type CallAsk } from "./voice-call-controller";
327	import { boundTranscript } from "./voice-call-record";
328	
329	export type CallStatus = "connecting" | "live" | "ended" | "error";
330	
331	function failure(cause: unknown) {
332	  const name = cause instanceof DOMException ? cause.name : "";
333	  if (name === "NotAllowedError" || name === "SecurityError") return "Microphone access was denied. Allow it in your browser to call Moneo.";
334	  if (name === "NotFoundError") return "No microphone was found.";
335	  return cause instanceof Error && cause.message ? cause.message : "Could not connect the call. Check your connection and try again.";
336	}
337	
338	/** Average loudness (0-1) of an analyser's current frame. */
339	function level(analyser: AnalyserNode | null, buffer: Uint8Array<ArrayBuffer>) {
340	  if (!analyser) return 0;
341	  analyser.getByteTimeDomainData(buffer);
342	  let sum = 0;
343	  for (const value of buffer) sum += ((value - 128) / 128) ** 2;
344	  return Math.min(1, Math.sqrt(sum / buffer.length) * 4);
345	}
346	
347	/** In development, a timed trace of the call (events, who is audible, what the controller decided) in the console and the dev server log. */
348	const trace = process.env.NODE_ENV === "production" ? undefined : (message: string) => console.info(`[call ${new Date().toISOString().slice(11, 23)}] ${message}`);
349	
350	/** Connection handles live outside React state; the controller, effect and orb share them. */
351	class Connection {
352	  channel: RTCDataChannel | null = null;
353	  mic: MediaStream | null = null;
354	  micLevel: AnalyserNode | null = null;
355	  moneoLevel: AnalyserNode | null = null;
356	  readonly aborts = new Map<string, AbortController>();
357	  /** The call's id and when it went live, for the record saved at hang-up. */
358	  readonly callId = crypto.randomUUID();
359	  startedAt: number | null = null;
360	  constructor(public onAnswer?: (question: string, answer: ChatAnswer) => void, public onEnded?: () => void) {}
361	  set(patch: Partial<Pick<Connection, "channel" | "mic" | "micLevel" | "moneoLevel" | "onAnswer" | "onEnded">>) { Object.assign(this, patch); }
362	}
