1	import type { ChatAnswer, ChatStreamEvent } from "./use-chat-request";
2	
3	export type CallCaption = { id: number; role: "user" | "assistant"; text: string };
4	export type CallTask = { requestId: string; text: string; step: string; status: "running" | "done" | "failed" | "canceled"; delegationId: string | null; cards: string[] };
5	export type CallAsk = (payload: { conversationId: string; requestId: string; message: string; context: Record<string, unknown> }, onEvent: (event: ChatStreamEvent) => void)
6	  => Promise<{ ok: boolean; status?: number; body: { error?: string } & Partial<ChatAnswer> }>;
7	
8	type ServerEvent = { type: string; delta?: string; end_ms?: number; offset_ms?: number | null; delegation?: { id: string }; error?: { message?: string }; message?: string };
9	type Deps = {
10	  conversationId: string;
11	  /** Sends a client event on the oai-events data channel. */
12	  send: (event: Record<string, unknown>) => void;
13	  ask: CallAsk;
14	  /** Called when a task's answer is saved in the chat, so the chat view can show it. */
15	  onAnswer?: (question: string, answer: ChatAnswer) => void;
16	  onChange: () => void;
17	  /** Notes what the call decided and when, for debugging a call. */
18	  log?: (message: string) => void;
19	  now?: () => number;
20	  schedule?: (run: () => void, ms: number) => unknown;
21	  newId?: () => string;
22	};
23	
24	/** What each chat tool is doing, as a short progress line for the voice model. */
25	const STEPS: Record<string, string> = {
26	  finance_investigate: "searching transactions", transactions_search: "searching transactions", finance_detail: "reading a transaction", finance_entities: "looking up names",
27	  finance_scenario: "comparing a what-if", analytics_cashflow: "adding up income and spending", accounts_list: "checking accounts", accounts_getBalances: "checking balances",
28	  forecast_evaluate: "running the forecast", goals_list: "checking goals", wealth_list: "checking what you lent and own", recurring_list: "checking recurring payments", reviews_investigate: "reviewing finances",
29	  reviews_start: "starting a deep review", imports_status: "checking imports", agents_findings: "reading agent findings", agents_decide: "making a confirmation card",
30	  transaction_propose: "making a card", iou_propose: "making a loan card", balance_propose: "making a balance card", recurring_propose: "making a recurring card",
31	  iou_findRepayments: "looking for repayments", call_replace_task: "replacing the earlier request", app_help: "checking how Moneo works",
32	};
33	export const stepFor = (tool: string) => STEPS[tool] ?? "working";
34	
35	/** The proposal card ids an answer shows, in order. */
36	export function answerCards(answer: string) {
37	  return [...new Set([...answer.matchAll(/```moneo-proposals?\n([\s\S]*?)```/g)].flatMap(match => match[1].match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi) ?? []))];
38	}
39	/** An answer as words to speak: no card, chart or decision blocks, bounded. */
40	export function spokenAnswer(answer: string, max = 1500) {
41	  const text = answer.replace(/```[\w-]*\n[\s\S]*?```/g, "").replace(/[*_#`>|]/g, "").replace(/\[([^\]]+)\]\([^)]*\)/g, "$1").replace(/\s+/g, " ").trim();
42	  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
43	}
44	
45	export const SPEAKING_HOLD_MS = 700;
46	/** Words still unclaimed after the user has been quiet this long were a request GPT-Live said yes to but never handed off. */
47	export const UNCLAIMED_MS = 4000;
48	const SMALL_TALK = /\b(hi|hey|hello|yo|thanks|thank you|bye|good (morning|evening|night)|how are you( doing)?( today)?|i'?m (good|fine|okay)|okay|ok|yeah|yes|no|um+|uh+|mm+|mm-?hm|(can|could|would|will) you( also)?( please)?( tell me| say)?)\b/gi;
49	const ASKS = /\?|\b(how much|what|when|where|who|which|why|check|show|tell|add|spent|spend|paid|pay|lent|lend|borrowed?|owe|bought|received|transfer|budget|save|balance|cancel|remove|change)\b/i;
50	/** Whether unclaimed words ask for something, rather than being small talk GPT-Live answered itself. */
51	export function looksLikeRequest(text: string) {
52	  const rest = text.replace(SMALL_TALK, " ").trim();
53	  return rest.split(/\s+/).filter(Boolean).length >= 3 && ASKS.test(rest);
54	}
55	export const SLOW_TASK_MS = 8000;
56	/** Moneo silent this long after it began saying a result means it said all of it. The user's words are transcribed
57	 * about a second late, so words arriving sooner than this were said over the result. */
58	export const RESULT_DONE_MS = 2500;
59	/** Longest wait for Moneo to start saying a result before the next is handed over anyway. */
60	export const RESULT_TURN_MS = 20_000;
61	/** A pause this long ends the user's turn for handing over a result; people pause mid-sentence ("uh… like…"). */
62	export const USER_PAUSE_MS = 1500;
63	/** How long Moneo gets to answer an interruption before it is asked to finish the result it was cut off in. */
64	export const RESUME_AFTER_MS = 3000;
65	
66	/**
67	 * Runs a voice call's tasks: each GPT-Live delegation (or typed message) becomes one /api/chat request, and its
68	 * answer is handed back to be spoken: first finished, first said, one at a time, and never over the user.
69	 */
70	export class VoiceCallController {
71	  captions: CallCaption[] = [];
72	  tasks: CallTask[] = [];
73	  error = "";
74	  /** Words the user said that no hand-off has claimed yet, with when each piece ended in the session. */
75	  private heard: { text: string; end: number }[] = [];
76	  private lastUserTurn = "";
77	  private lastDelegation: string | null = null;
78	  /** A request started from unclaimed words, which a late hand-off of the same words takes over instead of repeating. */
79	  private unclaimedTask: string | null = null;
80	  private answers = new Map<string, string>();
81	  private lastUserSpeech = -Infinity;
82	  private lastAssistantSpeech = -Infinity;
83	  /** When Moneo was last audible in the call's audio. Transcript text runs ahead of the voice, so once the audio is
84	   * metered it, not the transcript, says whether Moneo is talking. */
85	  private lastAudible = -Infinity;
86	  private metered = false;
87	  private outbox: { delegationId: string | null; content: string }[] = [];
88	  private flushing = false;
89	  /** The result Moneo was last handed and when, until it has said all of it or was talked over. */
90	  private current: { delegationId: string | null; content: string; at: number } | null = null;
91	  /** A result the user talked over, with what they said since, until Moneo is asked to finish it. */
92	  private cut: { delegationId: string | null; content: string; words: string } | null = null;
93	  private captionId = 0;
94	  /** A sound tag ("[scoff]") still open at the end of a role's last words, held until it closes. */
95	  private openTag: Record<CallCaption["role"], string> = { user: "", assistant: "" };
96	  private readonly now: () => number;
97	  private readonly schedule: (run: () => void, ms: number) => unknown;
98	  private readonly newId: () => string;
99	
100	  constructor(private readonly deps: Deps) {
101	    this.now = deps.now ?? (() => Date.now());
102	    this.schedule = deps.schedule ?? ((run, ms) => setTimeout(run, ms));
103	    this.newId = deps.newId ?? (() => crypto.randomUUID());
104	  }
105	
106	  get running() { return this.tasks.filter(task => task.status === "running"); }
107	  get cards() { return this.tasks.flatMap(task => task.cards); }
108	  /** When Moneo last made a sound: its metered voice once there is one, else its transcript. */
109	  private get lastMoneo() { return this.metered ? this.lastAudible : this.lastAssistantSpeech; }
110	  /** Someone is talking right now. */
111	  speaking(by: "user" | "any" = "any") {
112	    const last = by === "user" ? this.lastUserSpeech : Math.max(this.lastUserSpeech, this.lastMoneo);
113	    return this.now() - last < SPEAKING_HOLD_MS;
114	  }
115	  /** Called while Moneo's voice is audible in the call. */
116	  heardMoneo() { this.metered = true; this.lastAudible = this.now(); }
117	
118	  /** Whether Moneo has said the result it was handed: it began, then went quiet with nobody talking over it. */
119	  private resultSaid() {
120	    const current = this.current;
121	    if (!current) return true;
122	    const began = this.lastMoneo > current.at;
123	    return began ? this.now() - this.lastMoneo >= RESULT_DONE_MS : this.now() - current.at > RESULT_TURN_MS;
124	  }
125	
126	  handle(event: ServerEvent) {
127	    switch (event.type) {
128	      case "session.input_transcript.delta":
129	        // Talking over a result GPT-Live is saying stops it, and the rest would be lost.
130	        if (this.current && this.lastMoneo > this.current.at && !this.resultSaid()) {
131	          this.cut = { delegationId: this.current.delegationId, content: this.current.content, words: "" };
132	          this.deps.log?.(`cut off: ${this.current.content.slice(0, 60)}`);
133	          this.current = null;
134	          this.resume();
135	        }
136	        if (this.cut) this.cut.words += event.delta ?? "";
137	        this.lastUserSpeech = this.now();
138	        this.heard.push({ text: event.delta ?? "", end: event.end_ms ?? Infinity });
139	        this.caption("user", event.delta ?? "");
140	        this.schedule(() => this.claimUnheard(), UNCLAIMED_MS);
141	        break;
142	      case "session.output_transcript.delta":
143	        this.lastAssistantSpeech = this.now();
144	        this.caption("assistant", event.delta ?? "");
145	        break;
146	      case "session.delegation.created": {
147	        // The delegation carries no task text: it is what the user said up to its offset since the previous one;
148	        // words said after the offset belong to the next request.
149	        const offset = event.offset_ms ?? Infinity;
150	        const claimed = this.heard.some(piece => piece.end <= offset) ? this.heard.filter(piece => piece.end <= offset) : this.heard;
151	        this.heard = this.heard.filter(piece => !claimed.includes(piece));
152	        const words = claimed.map(piece => piece.text).join("").replace(/\[[^\]]*\]/g, "").trim();
153	        if (event.delegation?.id) this.lastDelegation = event.delegation.id;
154	        // A late hand-off for words already started as their own request answers through that one.
155	        if (event.delegation?.id && !words && this.unclaimedTask) { this.update(this.unclaimedTask, { delegationId: event.delegation.id }); this.unclaimedTask = null; break; }
156	        this.unclaimedTask = null;
157	        const text = words || this.lastUserTurn;
158	        if (event.delegation?.id && text) this.start(text, event.delegation.id);
159	        break;
160	      }
161	      case "error":
162	        this.error = event.error?.message ?? event.message ?? "The call had a problem";
163	        this.deps.onChange();
164	        break;
165	    }
166	  }
167	
168	  /**
169	   * GPT-Live sometimes says it is on a request ("sure, I'll check that too") without handing it off. Words that stay
170	   * unclaimed once the user has been quiet a while, and ask for something, become their own request, answered
171	   * through the latest hand-off. Small talk GPT-Live answered itself stays with it.
172	   */
173	  private claimUnheard() {
174	    if (this.now() - this.lastUserSpeech < UNCLAIMED_MS || !this.lastDelegation) return;
175	    const text = this.heard.map(piece => piece.text).join("").replace(/\[[^\]]*\]/g, "").trim();
176	    if (!looksLikeRequest(text)) return;
177	    this.heard = [];
178	    this.deps.log?.(`claimed words GPT-Live never handed off: ${text.slice(0, 60)}`);
179	    this.unclaimedTask = this.start(text, this.lastDelegation);
180	  }
181	
182	  /** A typed message starts a task directly; its answer is spoken the same way. */
183	  typed(text: string) {
184	    const message = text.trim();
185	    if (!message) return;
186	    this.captionId++;
187	    this.captions = [...this.captions, { id: this.captionId, role: "user", text: message }];
188	    this.start(message, null);
189	  }
190	
191	  private caption(role: CallCaption["role"], words: string) {
192	    // Sound tags are not words, and can arrive in pieces between the other side's words.
193	    let delta = (this.openTag[role] + words).replace(/\[[^\]]*\]/g, "");
194	    // A "[" that never closes within a few words was just a bracket.
195	    const open = delta.length - delta.lastIndexOf("[") > 40 ? -1 : delta.lastIndexOf("[");
196	    this.openTag[role] = open < 0 ? "" : delta.slice(open);
197	    if (open >= 0) delta = delta.slice(0, open);
198	    if (!delta) return;
199	    const last = this.captions.at(-1);
200	    if (last?.role === role) this.captions = [...this.captions.slice(0, -1), { ...last, text: last.text + delta }];
201	    else this.captions = [...this.captions, { id: ++this.captionId, role, text: delta.trimStart() }];
202	    if (role === "user") this.lastUserTurn = this.captions.at(-1)!.text.trim();
203	    this.deps.onChange();
204	  }
205	
206	  private update(requestId: string, change: Partial<CallTask>) {
207	    this.tasks = this.tasks.map(task => task.requestId === requestId ? { ...task, ...change } : task);
208	    this.deps.onChange();
209	  }
210	
211	  /**
212	   * What Moneo needs to answer one request on its own: the requests still being answered separately, the call so far
213	   * to resolve "that" or "also", and what this call has already answered.
214	   */
215	  private brief() {
216	    return {
217	      via: "call", input: "voice",
218	      runningTasks: this.running.slice(-5).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300) })),
219	      recentTurns: this.captions.slice(-6).map(caption => ({ role: caption.role, text: caption.text.slice(-300) })),
220	      answered: this.tasks.filter(task => this.answers.has(task.requestId)).slice(-4).map(task => ({ text: task.text.slice(0, 150), answer: this.answers.get(task.requestId)!.slice(0, 300) })),
221	    };
222	  }
223	
224	  private start(text: string, delegationId: string | null) {
225	    const requestId = this.newId();
226	    const context = this.brief();
227	    this.tasks = [...this.tasks, { requestId, text, step: "starting", status: "running", delegationId, cards: [] }];
228	    this.deps.onChange();
229	    this.watchSlow(requestId);
230	    void this.run(requestId, text, context);
231	    return requestId;
232	  }
233	
234	  private async run(requestId: string, text: string, context: ReturnType<VoiceCallController["brief"]>) {
235	    const label = `"${text.slice(0, 120)}"`;
236	    // Read when needed: a late hand-off can take a request over while it runs.
237	    const via = () => this.tasks.find(item => item.requestId === requestId)?.delegationId ?? null;
238	    try {
239	      const result = await this.deps.ask({ conversationId: this.deps.conversationId, requestId, message: text.slice(0, 4000), context }, event => {
240	        if (event.type !== "tool" || event.state !== "running") return;
241	        const step = stepFor(event.name);
242	        this.update(requestId, { step });
243	        if (via()) this.deps.send({ type: "session.thinking.append", delegation_id: via(), content: `Working on ${label}: ${step}.` });
244	      });
245	      const task = this.tasks.find(item => item.requestId === requestId);
246	      // Canceled from the list, or stopped because a correction replaced it: nothing to say.
247	      if (task?.status === "canceled" || result.status === 409) { this.update(requestId, { status: "canceled", step: "stopped" }); return; }
248	      if (!result.ok || !result.body.answer) throw new Error(result.body.error ?? "No answer");
249	      const cards = answerCards(result.body.answer);
250	      this.answers.set(requestId, spokenAnswer(result.body.answer));
251	      this.update(requestId, { status: "done", step: "answered", cards });
252	      this.deps.onAnswer?.(text, result.body as ChatAnswer);
253	      // A typed request has no hand-off to answer through, so the result says outright that it is to be spoken.
254	      const delegationId = via();
255	      this.deliver(delegationId, [`Result for ${label}${delegationId ? "" : " (typed by the user in the call; say the result to them now, in the language they typed)"}: ${spokenAnswer(result.body.answer)}`,
256	        cards.length ? `${cards.length} card${cards.length > 1 ? "s" : ""} on screen to tap; nothing is saved until then.` : ""].filter(Boolean).join(" "));
257	    } catch {
258	      if (this.tasks.find(item => item.requestId === requestId)?.status === "canceled") return;
259	      this.update(requestId, { status: "failed", step: "failed" });
260	      this.deliver(via(), `Moneo couldn't get an answer for ${label}. Tell the user briefly and ask if they want you to try again.`);
261	    }
262	  }
263	
264	  /** One short spoken update for a task that runs long, once nobody is talking. */
265	  private watchSlow(requestId: string, delay = SLOW_TASK_MS) {
266	    this.schedule(() => {
267	      const task = this.tasks.find(item => item.requestId === requestId);
268	      if (task?.status !== "running") return;
269	      // Never in the middle of saying a result, or before one waiting to be said.
270	      if (this.speaking() || this.current || this.cut || this.outbox.length) return this.watchSlow(requestId, 1000);
271	      this.deps.send({ type: "session.commentary.append", delegation_id: task.delegationId, content: `Still working on "${task.text.slice(0, 120)}" (${task.step}). Say so in a few words${task.delegationId ? "" : ", in the language they typed"}.` });
272	    }, delay);
273	  }
274	
275	  /** Results queue in the order they finish. */
276	  private deliver(delegationId: string | null, content: string) {
277	    this.outbox.push({ delegationId, content });
278	    this.flush();
279	  }
280	
281	  /**
282	   * Hands over the next result once Moneo has said the previous one and nobody is talking. What is still running is
283	   * read when it goes out, so a result never says another is pending after that one has finished.
284	   */
285	  private flush() {
286	    if (this.flushing || !this.outbox.length || this.cut) return;
287	    if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS || !this.resultSaid()) {
288	      this.flushing = true;
289	      this.schedule(() => { this.flushing = false; this.flush(); }, 300);
290	      return;
291	    }
292	    const { delegationId, content } = this.outbox.shift()!;
293	    const others = this.running.map(item => `"${item.text.slice(0, 80)}"`);
294	    this.current = { delegationId, content, at: this.now() };
295	    this.deps.log?.(`handed over: ${content.slice(0, 60)}`);
296	    this.deps.send({ type: "session.commentary.append", delegation_id: delegationId, content: others.length ? `${content} Still working on ${others.join(", ")}.` : content });
297	    this.flush();
298	  }
299	
300	  /**
301	   * Once the user has finished and Moneo has answered them (or had a few seconds to), Moneo is asked to finish the
302	   * result it was cut off in before any other. A short "mm-hm" over it is not an interruption.
303	   */
304	  private resume() {
305	    this.schedule(() => {
306	      const cut = this.cut;
307	      if (!cut) return;
308	      if (this.speaking() || this.now() - this.lastUserSpeech < USER_PAUSE_MS
309	        || (this.lastMoneo <= this.lastUserSpeech && this.now() - this.lastUserSpeech < RESUME_AFTER_MS)) return this.resume();
310	      this.cut = null;
311	      const words = cut.words.trim().split(/\s+/).length;
312	      this.deps.log?.(words >= 3 ? "resuming the cut-off result" : "not resuming: only a backchannel");
313	      if (words >= 3) this.outbox.unshift({ delegationId: cut.delegationId,
314	        content: `The user talked over you while you were giving this result. If you hadn't finished it, finish the part you hadn't said yet, without repeating what you already said; if you had, or they asked you to stop or skip it, say nothing more about it. ${cut.content}` });
315	      this.flush();
316	    }, 300);
317	  }
318	
319	  /** Marks a task canceled; the caller asks the server to stop it. */
320	  cancel(requestId: string) { this.update(requestId, { status: "canceled", step: "canceled" }); }
321	}
