  1	"use client";
  2	
  3	import { useEffect, useReducer, useState } from "react";
  4	import { readResponse, type ChatAnswer } from "./use-chat-request";
  5	import { VoiceCallController, type CallAsk } from "./voice-call-controller";
  6	import { boundTranscript } from "./voice-call-record";
  7	
  8	export type CallStatus = "connecting" | "live" | "ended" | "error";
  9	
 10	function failure(cause: unknown) {
 11	  const name = cause instanceof DOMException ? cause.name : "";
 12	  if (name === "NotAllowedError" || name === "SecurityError") return "Microphone access was denied. Allow it in your browser to call Moneo.";
 13	  if (name === "NotFoundError") return "No microphone was found.";
 14	  return cause instanceof Error && cause.message ? cause.message : "Could not connect the call. Check your connection and try again.";
 15	}
 16	
 17	/** Average loudness (0-1) of an analyser's current frame. */
 18	function level(analyser: AnalyserNode | null, buffer: Uint8Array<ArrayBuffer>) {
 19	  if (!analyser) return 0;
 20	  analyser.getByteTimeDomainData(buffer);
 21	  let sum = 0;
 22	  for (const value of buffer) sum += ((value - 128) / 128) ** 2;
 23	  return Math.min(1, Math.sqrt(sum / buffer.length) * 4);
 24	}
 25	
 26	/** In development, a timed trace of the call (events, who is audible, what the controller decided) in the console and the dev server log. */
 27	const trace = process.env.NODE_ENV === "production" ? undefined : (message: string) => console.info(`[call ${new Date().toISOString().slice(11, 23)}] ${message}`);
 28	
 29	/** Connection handles live outside React state; the controller, effect and orb share them. */
 30	class Connection {
 31	  channel: RTCDataChannel | null = null;
 32	  mic: MediaStream | null = null;
 33	  micLevel: AnalyserNode | null = null;
 34	  moneoLevel: AnalyserNode | null = null;
 35	  readonly aborts = new Map<string, AbortController>();
 36	  /** The call's id and when it went live, for the record saved at hang-up. */
 37	  readonly callId = crypto.randomUUID();
 38	  startedAt: number | null = null;
 39	  constructor(public onAnswer?: (question: string, answer: ChatAnswer) => void, public onEnded?: () => void) {}
 40	  set(patch: Partial<Pick<Connection, "channel" | "mic" | "micLevel" | "moneoLevel" | "onAnswer" | "onEnded">>) { Object.assign(this, patch); }
 41	}
 42	
 43	/**
 44	 * A live GPT-Live call over WebRTC. GPT-Live only talks; every question it hands off runs through /api/chat
 45	 * in this conversation (see VoiceCallController), and the answer is sent back for it to speak.
 46	 */
 47	export function useVoiceCall(conversationId: string, onAnswer?: (question: string, answer: ChatAnswer) => void, onEnded?: () => void) {
 48	  const [status, setStatus] = useState<CallStatus>("connecting");
 49	  const [error, setError] = useState("");
 50	  const [muted, setMuted] = useState(false);
 51	  const [, render] = useReducer((count: number) => count + 1, 0);
 52	  const [live] = useState(() => new Connection(onAnswer, onEnded));
 53	  useEffect(() => { live.set({ onAnswer, onEnded }); });
 54	
 55	  const [controller] = useState(() => {
 56	    const ask: CallAsk = async (payload, onEvent) => {
 57	      const abort = new AbortController();
 58	      live.aborts.set(payload.requestId, abort);
 59	      try {
 60	        const response = await fetch("/api/chat", { method: "POST", signal: abort.signal, headers: { "Content-Type": "application/json", Accept: "application/x-ndjson, application/json" }, body: JSON.stringify(payload) });
 61	        return await readResponse(response, onEvent);
 62	      } finally { live.aborts.delete(payload.requestId); }
 63	    };
 64	    return new VoiceCallController({ conversationId, ask, onChange: render, onAnswer: (question, answer) => live.onAnswer?.(question, answer),
 65	      log: trace,
 66	      send: event => {
 67	        trace?.(`sent ${event.type}: ${String(event.content ?? "").slice(0, 100)}`);
 68	        if (live.channel?.readyState === "open") live.channel.send(JSON.stringify(event));
 69	      } });
 70	  });
 71	
 72	  useEffect(() => {
 73	    let closed = false;
 74	    const pc = typeof RTCPeerConnection === "undefined" ? null : new RTCPeerConnection();
 75	    const audio = new Audio();
 76	    audio.autoplay = true;
 77	    let context: AudioContext | null = null, wakeLock: WakeLockSentinel | null = null;
 78	    const lock = () => { if (document.visibilityState === "visible") navigator.wakeLock?.request("screen").then(sentinel => { if (closed) void sentinel.release(); else wakeLock = sentinel; }, () => {}); };
 79	    async function connect() {
 80	      if (!pc || !navigator.mediaDevices?.getUserMedia) throw new Error("This browser cannot make voice calls. Try a recent Chrome, Safari or Firefox.");
 81	      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
 82	      if (closed) { stream.getTracks().forEach(track => track.stop()); return; }
 83	      live.set({ mic: stream });
 84	      context = new AudioContext();
 85	      const analyser = (source: MediaStream) => { const node = context!.createAnalyser(); node.fftSize = 512; context!.createMediaStreamSource(source).connect(node); return node; };
 86	      live.set({ micLevel: analyser(stream) });
 87	      pc.addTrack(stream.getAudioTracks()[0], stream);
 88	      pc.ontrack = event => { audio.srcObject = event.streams[0]; live.set({ moneoLevel: analyser(event.streams[0]) }); };
 89	      const dc = pc.createDataChannel("oai-events");
 90	      live.set({ channel: dc });
 91	      dc.onmessage = message => {
 92	        const event = JSON.parse(message.data);
 93	        if (event.type === "session.started") { setStatus("live"); live.startedAt ??= Date.now(); lock(); }
 94	        else if (event.type === "session.closed") setStatus("ended");
 95	        if (trace && event.type !== "session.output_audio.delta") trace(`${event.type}${event.delta !== undefined ? ` ${JSON.stringify(event.delta)}` : ""}${event.start_ms !== undefined ? ` ${event.start_ms}-${event.end_ms}ms` : ""}${event.offset_ms != null ? ` offset ${event.offset_ms}ms` : ""}`);
 96	        controller.handle(event);
 97	      };
 98	      pc.onconnectionstatechange = () => { if (!closed && pc.connectionState === "failed") { setStatus("error"); setError("The call dropped. Check your connection and try again."); } };
 99	      const offer = await pc.createOffer();
100	      await pc.setLocalDescription(offer);
101	      const response = await fetch("/api/voice/call", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ sdp: offer.sdp, conversationId }) });
102	      const body = await response.json().catch(() => ({}));
103	      if (!response.ok) throw new Error(body.error ?? "Could not start the call");
104	      if (!closed) await pc.setRemoteDescription({ type: "answer", sdp: body.sdp });
105	    }
106	    /** Hanging up saves the call in the chat; keepalive lets it finish even if the tab is closing. */
107	    function saveRecord() {
108	      const transcript = boundTranscript(controller.captions);
109	      if (live.startedAt === null || !transcript.length) return;
110	      const seconds = Math.min(86_400, Math.round((Date.now() - live.startedAt) / 1000));
111	      live.startedAt = null;
112	      // Answers that land after hang-up are saved by the server and shown inside the call.
113	      const finished = live.onEnded;
114	      live.set({ onAnswer: undefined });
115	      void fetch("/api/voice/calls", { method: "POST", keepalive: true, headers: { "Content-Type": "application/json" },
116	        body: JSON.stringify({ id: live.callId, conversationId, durationSeconds: seconds, transcript,
117	          tasks: controller.tasks.slice(-30).map(task => ({ requestId: task.requestId, text: task.text.slice(0, 300), status: task.status })) }) })
118	        .then(response => { if (response.ok) finished?.(); }, () => {});
119	    }
120	    connect().catch(cause => { if (!closed) { setStatus("error"); setError(failure(cause)); } });
121	    // Moneo's voice, metered: what the user actually hears decides when a result has been said.
122	    const buffer = new Uint8Array(512);
123	    let moneoOn = false, micOn = false;
124	    const meter = setInterval(() => {
125	      const moneo = level(live.moneoLevel, buffer) > 0.02, mic = level(live.micLevel, buffer) > 0.08;
126	      if (moneo) controller.heardMoneo();
127	      if (trace && moneo !== moneoOn) trace(moneo ? "Moneo audible" : "Moneo quiet");
128	      if (trace && mic !== micOn) trace(mic ? "mic loud" : "mic quiet");
129	      moneoOn = moneo; micOn = mic;
130	    }, 100);
131	    document.addEventListener("visibilitychange", lock);
132	    return () => {
133	      closed = true;
134	      clearInterval(meter);
135	      saveRecord();
136	      document.removeEventListener("visibilitychange", lock);
137	      try { if (live.channel?.readyState === "open") live.channel.send(JSON.stringify({ type: "session.close" })); } catch { /* already closed */ }
138	      live.set({ channel: null, micLevel: null, moneoLevel: null });
139	      live.mic?.getTracks().forEach(track => track.stop());
140	      pc?.close();
141	      audio.srcObject = null;
142	      void context?.close();
143	      void wakeLock?.release();
144	    };
145	  }, [controller, conversationId, live]);
146	
147	  function toggleMute() {
148	    const next = !muted;
149	    live.mic?.getAudioTracks().forEach(track => { track.enabled = !next; });
150	    setMuted(next);
151	  }
152	
153	  async function cancel(requestId: string) {
154	    controller.cancel(requestId);
155	    // Cancellation can arrive before the server has claimed the request.
156	    for (let attempt = 0; attempt < 10; attempt++) {
157	      const response = await fetch("/api/chat", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ requestId }) }).catch(() => null);
158	      if (response?.status !== 404) break;
159	      await new Promise(resolve => setTimeout(resolve, 100));
160	    }
161	    live.aborts.get(requestId)?.abort();
162	  }
163	
164	  /** Current loudness of the user's mic and of Moneo's voice, for the orb; read every frame without re-rendering. */
165	  const [levels] = useState(() => {
166	    const buffer = new Uint8Array(512);
167	    return () => ({ mic: level(live.micLevel, buffer), moneo: level(live.moneoLevel, buffer) });
168	  });
169	
170	  return {
171	    status, error: error || controller.error, muted, toggleMute, cancel, levels,
172	    captions: controller.captions, tasks: controller.tasks, cards: controller.cards,
173	    typed: (text: string) => controller.typed(text),
174	    /** Moneo is answering or working; used for the orb's thinking state. */
175	    thinking: controller.running.length > 0,
176	  };
177	}
  1	import { expect, it, vi } from "vitest";
  2	import { VoiceCallController, answerCards, looksLikeRequest, spokenAnswer, type CallAsk } from "./voice-call-controller";
  3	
  4	const card = "11111111-1111-4111-8111-111111111111";
  5	function setup() {
  6	  let clock = 0, ids = 0;
  7	  const timers: { at: number; run: () => void }[] = [];
  8	  const sent: Record<string, unknown>[] = [];
  9	  const pending: Record<string, (value: Awaited<ReturnType<CallAsk>>) => void> = {};
 10	  const asks: Parameters<CallAsk>[] = [];
 11	  const ask: CallAsk = (payload, onEvent) => { asks.push([payload, onEvent]); return new Promise(resolve => { pending[payload.message] = resolve; }); };
 12	  const onAnswer = vi.fn();
 13	  const call = new VoiceCallController({ conversationId: "c", send: event => sent.push(event), ask, onAnswer, onChange: () => {}, now: () => clock,
 14	    schedule: (run, ms) => timers.push({ at: clock + ms, run }), newId: () => `r${++ids}` });
 15	  const advance = async (ms: number) => {
 16	    clock += ms;
 17	    for (let due = timers.filter(timer => timer.at <= clock); due.length; due = timers.filter(timer => timer.at <= clock))
 18	      for (const timer of due) { timers.splice(timers.indexOf(timer), 1); timer.run(); }
 19	    await new Promise(resolve => setTimeout(resolve));
 20	  };
 21	  const say = (text: string, endMs?: number) => call.handle({ type: "session.input_transcript.delta", delta: text, end_ms: endMs });
 22	  const delegate = (id: string, offsetMs?: number) => call.handle({ type: "session.delegation.created", offset_ms: offsetMs, delegation: { id } });
 23	  const answer = async (message: string, text: string, status = 200) => { pending[message]({ ok: status < 400, status, body: status < 400 ? { answer: text, conversationId: "c" } : { error: "x" } }); await new Promise(resolve => setTimeout(resolve)); };
 24	  // Time passes in small steps, so retries the controller schedules run too; Moneo's voice is metered every 100 ms.
 25	  const wait = async (ms: number) => { for (let time = 0; time < ms; time += 100) await advance(100); };
 26	  const moneoTalks = async (ms: number) => { for (let time = 0; time < ms; time += 100) { call.heardMoneo(); await advance(100); } };
 27	  return { call, sent, asks, advance, wait, moneoTalks, say, delegate, answer, onAnswer };
 28	}
