 33	  say("And when is rent due?"); delegate("d2");
 34	  expect(asks.map(([payload]) => payload.message)).toEqual(["How much at Netto this month?", "And when is rent due?"]);
 35	  expect(asks[0][0]).toMatchObject({ conversationId: "c", requestId: "r1", context: { via: "call", input: "voice", runningTasks: [], answered: [] } });
 36	  // The second request knows the first is still running, so it neither answers it again nor misses a correction.
 37	  expect(asks[1][0].context).toMatchObject({ via: "call", input: "voice", runningTasks: [{ requestId: "r1", text: "How much at Netto this month?" }] });
 38	  asks[0][1]({ type: "tool", name: "finance_investigate", state: "running" });
 39	  expect(call.tasks[0].step).toBe("searching transactions");
 40	  expect(sent).toContainEqual({ type: "session.thinking.append", delegation_id: "d1", content: 'Working on "How much at Netto this month?": searching transactions.' });
 41	  expect(call.captions).toEqual([{ id: 1, role: "user", text: "How much at Netto this month?And when is rent due?" }]);
 42	});
