     1	// Real end-to-end check of the chat voice call. Costs real GPT-Live, TTS and chat-model usage.
     2	// Call 1 speaks test sentences (OpenAI TTS) into a fake mic and checks that delegations ran /api/chat, a card reached
     3	// the tray, Moneo's spoken answers show in the captions, the voice chosen in Settings is the session's voice, and that
     4	// after hang-up the chat shows one call summary card (summary, cards, transcript) that survives a reload.
     5	// Call 2 has a silent mic, types a message and checks that GPT-Live speaks the answer to it.
     6	// Run with the app up and e2e/.auth.json present (see scripts/e2e-auth.mjs); APP_URL defaults to http://localhost:3000:
     7	//   node --env-file=.env scripts/voice-call-check.mjs
     8	import { mkdirSync, writeFileSync } from "node:fs";
     9	import { resolve } from "node:path";
    10	import { chromium } from "@playwright/test";
    11	import postgres from "postgres";
    12	
    13	const base = process.env.APP_URL ?? "http://localhost:3000";
    14	const VOICE = "cedar";
    15	const sentences = [
    16	  "How much did I spend at Netto this month?",
    17	  "And when is my rent due?",
    18	  "Oh, by the way, I spent twelve euros forty in cash at Netto on chips and eggs.",
    19	];
    20	const pauses = [4, 2];
    21	const RATE = 24000;
    22	
    23	// The QA user's chat model may be an OpenRouter id without credits; the check needs a working OpenAI model.
    24	// It also picks a non-default voice, restored at the end.
    25	const db = process.env.SUPABASE_DB_URL ? postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} }) : null;
    26	let workspaceId, originalVoice = "marin";
    27	if (db && process.env.E2E_USER_EMAIL) {
    28	  const [row] = await db`select w.id as workspace_id, s.ai_models->>'chat' as chat, s.voice from public.workspaces w join auth.users u on u.id=w.owner_id
    29	    left join public.workspace_settings s on s.workspace_id=w.id where u.email=${process.env.E2E_USER_EMAIL}`;
    30	  workspaceId = row?.workspace_id;
    31	  originalVoice = row?.voice ?? "marin";
    32	  if (row?.chat?.includes("/")) {
    33	    await db`update public.workspace_settings set ai_models = ai_models - 'chat' where workspace_id=${workspaceId}`;
    34	    console.log(`chat model was ${row.chat}; reset to the default OpenAI model`);
    35	  }
    36	  await db`insert into public.workspace_settings(workspace_id, voice) values (${workspaceId}, ${VOICE}) on conflict (workspace_id) do update set voice = excluded.voice`;
    37	}
    38	
    39	async function speech(text) {
    40	  const response = await fetch("https://api.openai.com/v1/audio/speech", { method: "POST", headers: { Authorization: `Bearer ${process.env.OPENAI_API_KEY}`, "Content-Type": "application/json" },
    41	    body: JSON.stringify({ model: "gpt-4o-mini-tts", voice: "alloy", input: text, response_format: "pcm" }) });
    42	  if (!response.ok) throw new Error(`TTS failed: ${response.status} ${await response.text()}`);
    43	  return Buffer.from(await response.arrayBuffer());
    44	}
    45	const silence = seconds => Buffer.alloc(RATE * 2 * seconds);
    46	function writeWav(path, pcm) {
    47	  const header = Buffer.alloc(44);
    48	  header.write("RIFF", 0); header.writeUInt32LE(36 + pcm.length, 4); header.write("WAVE", 8); header.write("fmt ", 12);
    49	  header.writeUInt32LE(16, 16); header.writeUInt16LE(1, 20); header.writeUInt16LE(1, 22); header.writeUInt32LE(RATE, 24);
    50	  header.writeUInt32LE(RATE * 2, 28); header.writeUInt16LE(2, 32); header.writeUInt16LE(16, 34); header.write("data", 36); header.writeUInt32LE(pcm.length, 40);
    51	  writeFileSync(path, Buffer.concat([header, pcm]));
    52	  return resolve(path);
    53	}
    54	const clips = await Promise.all(sentences.map(speech));
    55	mkdirSync(".qa", { recursive: true });
    56	// Chrome loops the fake mic file, so a long silent tail keeps the questions from repeating during the check.
    57	const talking = writeWav(".qa/voice-call-check.wav", Buffer.concat([silence(3), ...clips.flatMap((clip, index) => [clip, silence(pauses[index] ?? 150)])]));
    58	const quiet = writeWav(".qa/voice-call-silence.wav", silence(120));
    59	
    60	/** Chat messages about Netto that are not inside the call card. */
    61	const outside = page => page.locator("article:not(:has([aria-label='Voice call']))").filter({ hasText: /Netto/ }).count();
    62	
    63	/** A browser whose fake mic plays `wav`, logging the call's data-channel events (not transcripts or audio). */
    64	async function open(wav) {
    65	  const browser = await chromium.launch({ args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream", `--use-file-for-fake-audio-capture=${wav}`, "--autoplay-policy=no-user-gesture-required"] });
    66	  const context = await browser.newContext({ storageState: "e2e/.auth.json", permissions: ["microphone"] });
    67	  const page = await context.newPage();
    68	  const log = [], chats = [], timing = {};
    69	  page.on("response", async response => {
    70	    if (!response.url().endsWith("/api/chat") || response.request().method() !== "POST") return;
    71	    const request = JSON.parse(response.request().postData() ?? "{}");
    72	    const text = await response.text().catch(() => "");
    73	    const result = text.trim().split("\n").map(line => { try { return JSON.parse(line); } catch { return null; } }).find(event => event?.type === "result");
    74	    chats.push({ message: request.message, via: request.context?.via, status: result?.status ?? response.status(), error: result?.body?.error });
    75	    console.log("chat", chats.at(-1));
    76	  });
    77	  page.on("console", message => {
    78	    const text = message.text();
    79	    if (text.startsWith("[call] started")) timing.sessionStartedAt ??= Date.now();
    80	    if (text.startsWith("[call] spoke")) timing.firstWordsAt ??= Date.now();
    81	    if (text.startsWith("[call]")) { log.push(text); if (!text.startsWith("[call] spoke")) console.log(text.slice(0, 220)); }
    82	    else if (message.type() === "error") console.log(text);
    83	  });
    84	  await page.addInitScript(() => {
    85	    const create = RTCPeerConnection.prototype.createDataChannel;
    86	    RTCPeerConnection.prototype.createDataChannel = function (...args) {
    87	      const channel = create.apply(this, args);
    88	      channel.addEventListener("message", message => {
    89	        const event = JSON.parse(message.data);
    90	        if (event.type === "session.started") console.log("[call] started voice=" + event.session?.audio?.output?.voice);
    91	        else if (event.type === "session.output_transcript.delta") console.log("[call] spoke " + (event.delta ?? ""));
    92	        else if (!/delta|usage/.test(event.type)) console.log("[call]", event.type, JSON.stringify(event).slice(0, 200));
    93	      });
    94	      const send = channel.send.bind(channel);
    95	      channel.send = data => { console.log("[call] sent", String(data).slice(0, 200)); send(data); };
    96	      return channel;
    97	    };
    98	  });
    99	  return { browser, page, log, chats, timing };
   100	}
   101	/** Clicks Call and waits until the call is live; `timing` gets when each step happened (ms after the click). */
   102	async function startCall(page, timing) {
   103	  await page.goto(`${base}/ai?conversation=new`);
   104	  await page.getByRole("button", { name: "Call" }).click();
   105	  const clicked = Date.now();
   106	  const call = page.getByRole("dialog", { name: "Voice call with Moneo" });
   107	  await call.getByRole("status").filter({ hasText: /Listening|Working|talking/ }).waitFor({ timeout: 30_000 });
   108	  timing.liveMs = Date.now() - clicked; timing.clicked = clicked;
   109	  console.log(`call is live ${timing.liveMs} ms after the click`);
   110	  return call;
   111	}
   112	
   113	// --- Call 1: spoken requests, voice, hang-up, summary card ---
   114	const first = await open(talking);
   115	const call = await startCall(first.page, first.timing);
   116	const deadline = Date.now() + 150_000;
   117	let cards = 0;
   118	while (Date.now() < deadline) {
   119	  await first.page.waitForTimeout(3000);
   120	  cards = await call.getByRole("region", { name: "Cards to review" }).getByRole("button").count();
   121	  if (first.chats.length >= 3 && cards > 0 && !(await call.getByRole("list", { name: "Tasks" }).locator("svg.lucide-loader-circle, svg.lucide-loader2").count())) { await first.page.waitForTimeout(12_000); break; }
   122	}
   123	const captions = await call.getByLabel("Live captions").innerText();
   124	const tasks = await call.getByRole("list", { name: "Tasks" }).innerText().catch(() => "");
   125	await first.page.screenshot({ path: ".qa/voice-call-check.png", fullPage: true });
   126	await call.getByRole("button", { name: /End call|Close/ }).click();
   127	
   128	const card = first.page.getByRole("region", { name: "Voice call", exact: true });
   129	let cardShown = false, summary = "";
   130	try {
   131	  await card.waitFor({ timeout: 30_000 });
   132	  cardShown = true;
   133	  // The summary is written after hang-up, so it can take a moment to appear.
   134	  await card.getByRole("list", { name: "Call summary" }).waitFor({ timeout: 90_000 });
   135	  summary = await card.getByRole("list", { name: "Call summary" }).innerText();
   136	} catch { /* reported below */ }
   137	const grouped = await outside(first.page);
   138	await card.getByText("Full transcript").click().catch(() => {});
   139	const transcript = await card.getByRole("list", { name: "Transcript" }).innerText().catch(() => "");
   140	const cardCards = await card.getByRole("region", { name: "Cards from this call" }).locator("section").first().waitFor({ timeout: 20_000 }).then(() => 1, () => 0);
   141	await card.getByText(/Requests from this call/).click().catch(() => {});
   142	await first.page.screenshot({ path: ".qa/voice-call-card.png", fullPage: true });
   143	// The same card comes back from the saved record after a reload.
   144	await first.page.reload();
   145	const reloaded = await first.page.getByRole("region", { name: "Voice call", exact: true }).waitFor({ timeout: 30_000 }).then(() => true, () => false);
   146	const duplicates = await outside(first.page);
   147	const afterClick = at => at ? `${at - first.timing.clicked} ms after the click` : "not heard";
   148	console.log(`timings: live ${first.timing.liveMs} ms; session started ${afterClick(first.timing.sessionStartedAt)}; Moneo's first spoken words ${afterClick(first.timing.firstWordsAt)}`);
   149	const voiceStarted = first.log.find(line => line.startsWith("[call] started"));
   150	await first.browser.close();
   151	
   152	console.log("\n--- captions ---\n" + captions + "\n--- tasks ---\n" + tasks + "\n--- summary ---\n" + summary + "\n--- transcript ---\n" + transcript.slice(0, 600));
   153	
   154	// --- Call 2: a typed message must be spoken ---
   155	const second = await open(quiet);
   156	const quietCall = await startCall(second.page, second.timing);
   157	await second.page.waitForTimeout(2000);
   158	await quietCall.getByLabel("Type to Moneo").fill("How much did I spend at Netto this month?");
   159	await quietCall.getByRole("button", { name: "Send" }).click();
   160	// The mic is silent, so speech after the result was handed over is Moneo saying it (GPT-Live may answer in another
   161	// language, so this counts speech rather than matching words).
   162	let spoken = false;
   163	for (const end = Date.now() + 90_000; Date.now() < end && !spoken; await second.page.waitForTimeout(2000)) {
   164	  const results = second.log.findIndex(line => line.startsWith("[call] sent") && line.includes("commentary.append") && line.includes("Result for"));
   165	  spoken = results >= 0 && second.log.slice(results).filter(line => line.startsWith("[call] spoke")).length >= 12;
   166	}
   167	const typedCaptions = await quietCall.getByLabel("Live captions").innerText();
   168	console.log("\n--- typed call captions ---\n" + typedCaptions);
   169	await second.browser.close();
   170	
   171	if (db) {
   172	  await db`update public.workspace_settings set voice=${originalVoice} where workspace_id=${workspaceId}`;
   173	  await db.end();
   174	}
   175	const checks = {
   176	  "delegations ran /api/chat in call mode": first.chats.length >= 2 && first.chats.every(chat => chat.via === "call"),
   177	  "chat requests completed": first.chats.filter(chat => chat.status === 200).length >= 2,
   178	  "a card is in the tray": cards > 0,
   179	  "Moneo spoke answers": /Moneo: /.test(captions) || captions.split("\n").length > 3,
   180	  [`the call used the chosen voice (${VOICE})`]: voiceStarted === `[call] started voice=${VOICE}`,
   181	  "hanging up shows one call summary card": cardShown,
   182	  "the card has a 2-4 bullet summary": summary.split("\n").filter(Boolean).length >= 1 && summary.split("\n").filter(Boolean).length <= 4,
   183	  "the card keeps both speakers in its transcript": /You: /.test(transcript) && /Moneo: /.test(transcript),
   184	  "the card shows the cards made during the call": cardCards > 0,
   185	  "the call's messages are not repeated outside the card": grouped === 0 && duplicates === 0,
   186	  "the card is still there after a reload": reloaded,
   187	  "a typed message during the call is spoken": spoken,
   188	};
   189	for (const [name, ok] of Object.entries(checks)) console.log(`${ok ? "PASS" : "FAIL"} ${name}`);
   190	process.exit(Object.values(checks).every(Boolean) ? 0 : 1);
