   101	/** Clicks Call and waits until the call is live; `timing` gets when each step happened (ms after the click). */
   102	async function startCall(page, timing) {
   103	  await page.goto(`${base}/ai?conversation=new`);
   104	  await page.getByRole("button", { name: "Call" }).click();
   105	  const clicked = Date.now();
   106	  const call = page.getByRole("dialog", { name: "Voice call with Moneo" });
   107	  await call.getByRole("status").filter({ hasText: /Listening|Working|talking/ }).waitFor({ timeout: 30_000 });
   108	  timing.liveMs = Date.now() - clicked; timing.clicked = clicked;
   109	  console.log(`call is live ${timing.liveMs} ms after the click`);
   110	  return call;
   111	}
   112	
   113	// --- Call 1: spoken requests, voice, hang-up, summary card ---
   114	const first = await open(talking);
   115	const call = await startCall(first.page, first.timing);
   116	const deadline = Date.now() + 150_000;
   117	let cards = 0;
   118	while (Date.now() < deadline) {
   119	  await first.page.waitForTimeout(3000);
   120	  cards = await call.getByRole("region", { name: "Cards to review" }).getByRole("button").count();
   121	  if (first.chats.length >= 3 && cards > 0 && !(await call.getByRole("list", { name: "Tasks" }).locator("svg.lucide-loader-circle, svg.lucide-loader2").count())) { await first.page.waitForTimeout(12_000); break; }
   122	}
   123	const captions = await call.getByLabel("Live captions").innerText();
   124	const tasks = await call.getByRole("list", { name: "Tasks" }).innerText().catch(() => "");
   125	await first.page.screenshot({ path: ".qa/voice-call-check.png", fullPage: true });
   126	await call.getByRole("button", { name: /End call|Close/ }).click();
   127	
   128	const card = first.page.getByRole("region", { name: "Voice call", exact: true });
   129	let cardShown = false, summary = "";
   130	try {
   131	  await card.waitFor({ timeout: 30_000 });
   132	  cardShown = true;
   133	  // The summary is written after hang-up, so it can take a moment to appear.
   134	  await card.getByRole("list", { name: "Call summary" }).waitFor({ timeout: 90_000 });
   135	  summary = await card.getByRole("list", { name: "Call summary" }).innerText();
   136	} catch { /* reported below */ }
   137	const grouped = await outside(first.page);
   138	await card.getByText("Full transcript").click().catch(() => {});
   139	const transcript = await card.getByRole("list", { name: "Transcript" }).innerText().catch(() => "");
   140	const cardCards = await card.getByRole("region", { name: "Cards from this call" }).locator("section").first().waitFor({ timeout: 20_000 }).then(() => 1, () => 0);
   141	await card.getByText(/Requests from this call/).click().catch(() => {});
   142	await first.page.screenshot({ path: ".qa/voice-call-card.png", fullPage: true });
   143	// The same card comes back from the saved record after a reload.
   144	await first.page.reload();
   145	const reloaded = await first.page.getByRole("region", { name: "Voice call", exact: true }).waitFor({ timeout: 30_000 }).then(() => true, () => false);
   146	const duplicates = await outside(first.page);
   147	const afterClick = at => at ? `${at - first.timing.clicked} ms after the click` : "not heard";
   148	console.log(`timings: live ${first.timing.liveMs} ms; session started ${afterClick(first.timing.sessionStartedAt)}; Moneo's first spoken words ${afterClick(first.timing.firstWordsAt)}`);
   149	const voiceStarted = first.log.find(line => line.startsWith("[call] started"));
   150	await first.browser.close();
   151	
   152	console.log("\n--- captions ---\n" + captions + "\n--- tasks ---\n" + tasks + "\n--- summary ---\n" + summary + "\n--- transcript ---\n" + transcript.slice(0, 600));
   153	
   154	// --- Call 2: a typed message must be spoken ---
   155	const second = await open(quiet);
   156	const quietCall = await startCall(second.page, second.timing);
   157	await second.page.waitForTimeout(2000);
   158	await quietCall.getByLabel("Type to Moneo").fill("How much did I spend at Netto this month?");
   159	await quietCall.getByRole("button", { name: "Send" }).click();
   160	// The mic is silent, so speech after the result was handed over is Moneo saying it (GPT-Live may answer in another
   161	// language, so this counts speech rather than matching words).
   162	let spoken = false;
   163	for (const end = Date.now() + 90_000; Date.now() < end && !spoken; await second.page.waitForTimeout(2000)) {
   164	  const results = second.log.findIndex(line => line.startsWith("[call] sent") && line.includes("commentary.append") && line.includes("Result for"));
   165	  spoken = results >= 0 && second.log.slice(results).filter(line => line.startsWith("[call] spoke")).length >= 12;
   166	}
   167	const typedCaptions = await quietCall.getByLabel("Live captions").innerText();
   168	console.log("\n--- typed call captions ---\n" + typedCaptions);
   169	await second.browser.close();
   170	
   171	if (db) {
   172	  await db`update public.workspace_settings set voice=${originalVoice} where workspace_id=${workspaceId}`;
   173	  await db.end();
   174	}
   175	const checks = {
   176	  "delegations ran /api/chat in call mode": first.chats.length >= 2 && first.chats.every(chat => chat.via === "call"),
   177	  "chat requests completed": first.chats.filter(chat => chat.status === 200).length >= 2,
   178	  "a card is in the tray": cards > 0,
   179	  "Moneo spoke answers": /Moneo: /.test(captions) || captions.split("\n").length > 3,
   180	  [`the call used the chosen voice (${VOICE})`]: voiceStarted === `[call] started voice=${VOICE}`,
   181	  "hanging up shows one call summary card": cardShown,
   182	  "the card has a 2-4 bullet summary": summary.split("\n").filter(Boolean).length >= 1 && summary.split("\n").filter(Boolean).length <= 4,
   183	  "the card keeps both speakers in its transcript": /You: /.test(transcript) && /Moneo: /.test(transcript),
   184	  "the card shows the cards made during the call": cardCards > 0,
   185	  "the call's messages are not repeated outside the card": grouped === 0 && duplicates === 0,
   186	  "the card is still there after a reload": reloaded,
   187	  "a typed message during the call is spoken": spoken,
   188	};
   189	for (const [name, ok] of Object.entries(checks)) console.log(`${ok ? "PASS" : "FAIL"} ${name}`);
   190	process.exit(Object.values(checks).every(Boolean) ? 0 : 1);
