--- dace70f8 Start a request GPT-Live agreed to but never handed off
In a call GPT-Live said "I'm on that one too" for last month without handing it off, so it was folded into the next request. Words left unclaimed for 4 s that ask for something now become their own request; small talk stays with GPT-Live, and a late hand-off takes the request over instead of repeating it. GPT-Live is also told that agreeing to check something needs its own hand-off.

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Entire-Checkpoint: 01M66D2RJ28FGE66R2C99FDF4H

--- 9d3e909d Leave sound tags like [scoff] out of call transcripts and requests
Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Entire-Checkpoint: 01M66CMZ21X029ZH8QKVAB4GFX

--- bc1a5c72 Brief each call request with the call so far, and cut it at its hand-off's timestamp
Moneo now gets the recent call turns, the requests still running and what the call already answered, and is told to answer only its own request and skip small talk. A request is the words said up to its hand-off's offset, and words GPT-Live never handed off no longer become a task on their own.

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Entire-Checkpoint: 01M6692M1QV0TMK4FX6ARS3ETV

--- d3ac5759 Let chat cards record their request, and start tasks for requests GPT-Live never handed off
Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Entire-Checkpoint: 01M65DC10D4HNH5PCFR650KPD7

--- d75c9bb8 Add the voice call controller that turns delegations into chat requests and speaks their results
Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
Entire-Checkpoint: 01M650RNQ25EBDN1ZKH3MBWX45

     1	"use client";
     2	
     3	import { useEffect, useRef, useState } from "react";
     4	import { AlertCircle, ArrowUp, Ban, CheckCircle2, Loader2, Mic, MicOff, PhoneOff, X } from "lucide-react";
     5	import { IouCard } from "@/components/iou-card";
     6	import { useVoiceCall } from "@/lib/ai/use-voice-call";
     7	import type { ChatAnswer } from "@/lib/ai/use-chat-request";
     8	
     9	type OrbState = "connecting" | "listening" | "muted" | "thinking" | "speaking" | "idle";
    10	const ORB_TONES: Record<OrbState, string> = {
    11	  connecting: "[--orb-a:var(--color-ai-border)] [--orb-b:var(--color-ai-soft)]",
    12	  listening: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-ai-border)]",
    13	  muted: "[--orb-a:var(--color-subtle)] [--orb-b:var(--color-muted)]",
    14	  thinking: "[--orb-a:var(--color-ai)] [--orb-b:var(--color-lime)]",
    15	  speaking: "[--orb-a:var(--color-lime)] [--orb-b:var(--color-brand)]",
    16	  idle: "[--orb-a:var(--color-input)] [--orb-b:var(--color-muted)]",
    17	};
    18	
    19	/** The orb follows whoever is talking: its glow and ring swell with the voice, it turns while Moneo works, and it holds still for reduced motion. */
    20	function Orb({ levels, state }: { levels: () => { mic: number; moneo: number }; state: OrbState }) {
    21	  const orb = useRef<HTMLDivElement>(null);
    22	  useEffect(() => {
    23	    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    24	    let frame = 0, smooth = 0;
    25	    const tick = () => {
    26	      const { mic, moneo } = levels();
    27	      smooth += (Math.max(mic, moneo) - smooth) * 0.2;
    28	      orb.current?.style.setProperty("--level", smooth.toFixed(3));
    29	      frame = requestAnimationFrame(tick);
    30	    };
    31	    frame = requestAnimationFrame(tick);
    32	    return () => cancelAnimationFrame(frame);
    33	  }, [levels]);
    34	  const still = state === "idle" || state === "muted";
    35	  return <div ref={orb} aria-hidden="true" className={`relative grid size-36 shrink-0 place-items-center sm:size-52 ${ORB_TONES[state]}`}>
    36	    <div className="absolute inset-2 rounded-full bg-[radial-gradient(circle,var(--orb-a),transparent_68%)] opacity-45 blur-2xl" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.5))" }} />
    37	    <div className="absolute inset-4 rounded-full border sm:inset-5 border-[color-mix(in_oklab,var(--orb-a)_40%,transparent)]" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.3))" }} />
    38	    <div className={still ? "" : "motion-safe:animate-orb-breathe"}>
    39	      <div className="relative size-24 overflow-hidden rounded-full shadow-[inset_0_-10px_30px_rgb(0_0_0/0.18),0_14px_40px_-14px_var(--orb-a)] sm:size-32" style={{ transform: "scale(calc(1 + var(--level, 0) * 0.14))" }}>
    40	        <div className={`absolute -inset-1/4 blur-md bg-[conic-gradient(from_90deg,var(--orb-a),var(--orb-b),var(--orb-a))] ${state === "thinking" || state === "connecting" ? "motion-safe:animate-orb-spin" : ""}`} />
    41	        <div className="absolute inset-0 rounded-full bg-[radial-gradient(circle_at_32%_28%,rgb(255_255_255/0.5),transparent_48%)]" />
    42	      </div>
    43	    </div>
    44	  </div>;
    45	}
    46	
    47	/** A live voice call with Moneo: speak or type, see the requests it is working on, and tap the cards it makes. The full transcript is saved with the call. */
    48	export function VoiceCall({ conversationId, onAnswer, onEnded, onClose }: { conversationId: string; onAnswer: (question: string, answer: ChatAnswer) => void; onEnded: () => void; onClose: () => void }) {
    49	  return <VoiceCallView call={useVoiceCall(conversationId, onAnswer, onEnded)} onClose={onClose} />;
    50	}
    51	
    52	/** The call screen for a call's state, kept apart from the connection so each state can be rendered alone. */
    53	export function VoiceCallView({ call, onClose }: { call: ReturnType<typeof useVoiceCall>; onClose: () => void }) {
    54	  const [text, setText] = useState("");
    55	  const body = useRef<HTMLDivElement>(null);
    56	  useEffect(() => { body.current?.scrollTo({ top: body.current.scrollHeight }); }, [call.tasks]);
    57	  const last = call.captions.at(-1);
    58	  const live = call.status === "live";
    59	  const open = live || call.status === "connecting";
    60	  const state: OrbState = call.status === "connecting" ? "connecting" : !live ? "idle" : last?.role === "assistant" && !call.thinking ? "speaking" : call.thinking ? "thinking" : call.muted ? "muted" : "listening";
    61	  const label = { connecting: "Connecting…", listening: "Listening", muted: "You're muted", thinking: "Working on it", speaking: "Moneo is talking", idle: call.status === "ended" ? "Call ended" : "Call dropped" }[state];
    62	  const running = call.tasks.filter(task => task.status === "running");
    63	  const round = "grid size-16 place-items-center rounded-full transition-[background-color,transform] active:scale-95 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-40";
    64	
    65	  return <section role="dialog" aria-modal="true" aria-label="Voice call with Moneo" className="fixed inset-0 z-50 flex flex-col bg-background lg:sticky lg:top-19 lg:z-auto lg:h-[calc(100dvh-4.75rem)]">
    66	    <header className="flex items-center justify-between gap-3 border-b border-border px-4 pt-[max(0.75rem,env(safe-area-inset-top))] pb-3 sm:px-8 lg:pt-3">
    67	      <p className="font-display text-lg font-semibold">Call with Moneo</p>
    68	      {live && <span className="inline-flex items-center gap-1.5 rounded-full bg-success-soft px-2.5 py-1 text-xs font-medium text-success"><span className="size-1.5 rounded-full bg-current motion-safe:animate-pulse" aria-hidden="true" />Live</span>}
    69	    </header>
    70	    <div ref={body} className="scrollbar-none mx-auto flex min-h-0 w-full max-w-[720px] flex-1 flex-col overflow-y-auto px-4 sm:px-8">
    71	      <div className="flex flex-col items-center pt-4 sm:pt-8">
    72	        <Orb levels={call.levels} state={state} />
    73	        <p role="status" className="flex h-7 items-center gap-2 font-display text-lg font-medium">{state === "connecting" && <Loader2 className="size-4 text-ai motion-safe:animate-spin" aria-hidden="true" />}{label}</p>
    74	      </div>
    75	      {call.error && <p role="alert" className="mt-4 flex items-start gap-2 rounded-xl border border-danger/30 bg-danger-soft px-3.5 py-2.5 text-sm text-danger"><AlertCircle className="mt-0.5 size-4 shrink-0" aria-hidden="true" />{call.error}</p>}
    76	      {!call.tasks.length && live && <p className="mt-6 text-center text-[15px] text-muted-foreground sm:text-base">Say hi, ask about your money, or tell Moneo what you spent.</p>}
    77	      {call.tasks.length > 0 && <div className="mt-5">
    78	        <p className="eyebrow pb-2">{running.length ? `Working on ${running.length} of ${call.tasks.length}` : "All done"}</p>
    79	        <ul className="space-y-1.5" aria-label="Tasks">
    80	          {call.tasks.slice(-6).map(task => <li key={task.requestId} className="flex min-h-14 items-center gap-3 rounded-xl border border-border bg-card py-1.5 pr-1 pl-3.5 text-sm">
    81	            <TaskIcon status={task.status} />
    82	            <span className="min-w-0 flex-1"><span className="block truncate font-medium">{task.text}</span><span className={`block text-xs ${task.status === "failed" ? "text-danger" : "text-muted-foreground"}`}>{task.step}</span></span>
    83	            {task.status === "running" && <button type="button" onClick={() => void call.cancel(task.requestId)} aria-label={`Stop “${task.text}”`} className="grid size-11 shrink-0 place-items-center rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-ai"><X className="size-4" aria-hidden="true" /></button>}
    84	          </li>)}
    85	        </ul>
    86	      </div>}
    87	      {call.cards.length > 0 && <div aria-label="Cards to review" role="region" className="mt-5">
    88	        <p className="eyebrow">Tap to save · nothing is saved until you do</p>
    89	        {call.cards.map(id => <IouCard key={id} id={id} />)}
    90	      </div>}
    91	      <div className="h-4 shrink-0" />
    92	    </div>
    93	    <footer className="border-t border-border px-4 pt-3 pb-[max(1rem,env(safe-area-inset-bottom))] sm:px-8">
    94	      {open && <form onSubmit={event => { event.preventDefault(); call.typed(text); setText(""); }} className="mx-auto mb-4 flex max-w-[720px] items-center gap-2">
    95	        <label className="sr-only" htmlFor="call-text">Type to Moneo</label>
    96	        <input id="call-text" value={text} onChange={event => setText(event.target.value)} maxLength={4000} placeholder="Or type a message…" autoComplete="off"
    97	          className="h-11 min-w-0 flex-1 rounded-full border border-input bg-card px-4 text-[15px] transition-colors focus:border-muted-foreground/60 focus:outline-none" />
    98	        <button aria-label="Send" disabled={!text.trim()} className="grid size-11 shrink-0 place-items-center rounded-full bg-primary text-primary-foreground transition-opacity hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai disabled:opacity-30"><ArrowUp className="size-5" aria-hidden="true" /></button>
    99	      </form>}
   100	      <div className="flex items-start justify-center gap-10">
   101	        <div className="flex flex-col items-center gap-1.5">
   102	          <button type="button" onClick={call.toggleMute} aria-pressed={call.muted} aria-label={call.muted ? "Unmute" : "Mute"} disabled={!live}
   103	            className={`${round} ${call.muted ? "bg-foreground text-background" : "border border-border bg-card hover:bg-muted"}`}>{call.muted ? <MicOff className="size-6" aria-hidden="true" /> : <Mic className="size-6" aria-hidden="true" />}</button>
   104	          <span aria-hidden="true" className="text-xs text-muted-foreground">{call.muted ? "Unmute" : "Mute"}</span>
   105	        </div>
   106	        <div className="flex flex-col items-center gap-1.5">
   107	          <button type="button" onClick={onClose} aria-label={open ? "End call" : "Close"} className={`${round} bg-danger text-white hover:bg-danger/90`}>{open ? <PhoneOff className="size-6" aria-hidden="true" /> : <X className="size-6" aria-hidden="true" />}</button>
   108	          <span aria-hidden="true" className="text-xs text-muted-foreground">{open ? "End" : "Close"}</span>
   109	        </div>
   110	      </div>
   111	    </footer>
   112	  </section>;
   113	}
   114	
   115	/** Where one task stands: a spinner while running, then a tick, a warning or a stop mark. */
   116	function TaskIcon({ status }: { status: string }) {
   117	  const icon = "size-4 shrink-0";
   118	  if (status === "running") return <Loader2 className={`${icon} text-ai motion-safe:animate-spin`} aria-label="Running" />;
   119	  if (status === "done") return <CheckCircle2 className={`${icon} text-success`} aria-label="Done" />;
   120	  if (status === "failed") return <AlertCircle className={`${icon} text-danger`} aria-label="Failed" />;
   121	  return <Ban className={`${icon} text-subtle`} aria-label="Stopped" />;
   122	}

