    44	/** Long calls keep their start and end, so the prompt stays bounded. */
    45	export function summaryInput(transcript: CallTurn[], limit = SUMMARY_INPUT_CHARS) {
    46	  const text = transcript.map(turn => `${turn.role === "user" ? "User" : "Moneo"}: ${turn.text}`).join("\n");
    47	  return text.length <= limit ? text : `${text.slice(0, limit / 2)}\n[…]\n${text.slice(-limit / 2)}`;
